-- ============================================================
-- Coolbox - datos iniciales (se ejecuta en cada arranque)
-- Es idempotente: no duplica datos ni borra lo que registres en el programa.
-- ============================================================

-- 1. Promociones y descuento (igual que el modelo de Power Architect)
CREATE TABLE IF NOT EXISTS promocion (
    id_promocion INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre       VARCHAR(60) NOT NULL,
    descripcion  VARCHAR(150),
    porcentaje   DOUBLE PRECISION NOT NULL,
    fecha_inicio DATE NOT NULL,
    fecha_fin    DATE NOT NULL,
    estado       VARCHAR(10) NOT NULL
);
ALTER TABLE venta ADD COLUMN IF NOT EXISTS id_promocion INTEGER;
ALTER TABLE venta ADD COLUMN IF NOT EXISTS descuento DOUBLE PRECISION DEFAULT 0 NOT NULL;
ALTER TABLE venta ADD CONSTRAINT IF NOT EXISTS promocion_venta_fk FOREIGN KEY (id_promocion) REFERENCES promocion (id_promocion);

-- Login de proveedores: la cuenta de usuario puede pertenecer a un proveedor
ALTER TABLE usuario ADD COLUMN IF NOT EXISTS id_proveedor INTEGER;
ALTER TABLE usuario ADD CONSTRAINT IF NOT EXISTS proveedor_usuario_fk FOREIGN KEY (id_proveedor) REFERENCES proveedor (id_proveedor);

-- 2. Perfiles y usuarios. Las claves estan encriptadas con SHA-256 (ver PasswordUtil):
--    admin -> admin123   |   yazminvs -> yaz123   |   pepe -> pepe12   |   vendedor -> vend123   |   proveedor -> prov123
MERGE INTO perfil (id_perfil, nombre, codigo) KEY (id_perfil) VALUES (1, 'Root', 'ROOT'), (2, 'Administrador', 'ADM'), (3, 'Reporte', 'REP'), (4, 'Proveedor', 'PRO');
MERGE INTO usuario (id_usuario, usuario, clave, estado, id_perfil) KEY (id_usuario)
    VALUES (1, 'admin', 'JAvlGPq9JyTdtvBO6x2llnRI1+gxwIyPqCKAn3THIKk=', 'ACTIVO', 1),
           (2, 'yazminvs', 'jAgi9Yuk7cB0k8ZeTP9Xnxl0i/j4rI4oO3s715887OY=', 'ACTIVO', 1),
           (3, 'pepe', 'VOAgbfArhzKivGJ+QynTGX7VJ8SE4dXtewfojvRj72c=', 'ACTIVO', 3);

-- 3. Los contadores de ID continuan despues del ultimo registro
--    (evita el error 'Unique index or primary key violation' al registrar desde el programa)
ALTER TABLE perfil ALTER COLUMN id_perfil RESTART WITH (SELECT COALESCE(MAX(id_perfil), 0) + 1 FROM perfil);
ALTER TABLE usuario ALTER COLUMN id_usuario RESTART WITH (SELECT COALESCE(MAX(id_usuario), 0) + 1 FROM usuario);
ALTER TABLE categoria ALTER COLUMN id_categoria RESTART WITH (SELECT COALESCE(MAX(id_categoria), 0) + 1 FROM categoria);
ALTER TABLE marca ALTER COLUMN id_marca RESTART WITH (SELECT COALESCE(MAX(id_marca), 0) + 1 FROM marca);
ALTER TABLE unid_medida ALTER COLUMN id_unidad RESTART WITH (SELECT COALESCE(MAX(id_unidad), 0) + 1 FROM unid_medida);
ALTER TABLE producto ALTER COLUMN id_producto RESTART WITH (SELECT COALESCE(MAX(id_producto), 0) + 1 FROM producto);
ALTER TABLE emisor ALTER COLUMN id_emisor RESTART WITH (SELECT COALESCE(MAX(id_emisor), 0) + 1 FROM emisor);
ALTER TABLE promocion ALTER COLUMN id_promocion RESTART WITH (SELECT COALESCE(MAX(id_promocion), 0) + 1 FROM promocion);

